-- ============================================================================
-- Faith Dash — global leaderboard schema for Supabase (PostgreSQL)
-- Run this whole file once in: Supabase Dashboard -> SQL Editor -> New query -> Run.
-- GENERATED by scripts/gen-sql.mjs from the real level definitions. Re-run the script if levels change.
-- Security model: RLS is ON for every table with NO anon policies, so browsers cannot read or write
-- tables directly. All access goes through the SECURITY DEFINER functions below, which validate input.
-- ============================================================================

create extension if not exists pgcrypto;

-- ---------- reference data ----------
create table if not exists public.levels (
  level_id    int primary key,
  name        text not null,
  speed       numeric not null,        -- tiles per second (the player's constant forward speed)
  length_m    numeric not null,        -- level length in metres (tiles)
  max_coins   int not null             -- number of mandatory trivia coins
);
insert into public.levels (level_id, name, speed, length_m, max_coins) values
  (1, 'The Beginning', 9, 675, 5),
  (2, 'The Journey', 10.5, 900, 7),
  (3, 'The Trial', 12, 1170, 9)
on conflict (level_id) do update set name = excluded.name, speed = excluded.speed, length_m = excluded.length_m, max_coins = excluded.max_coins;

-- ---------- players (anonymous; identified by a random UUID generated on the device) ----------
create table if not exists public.players (
  player_id    uuid primary key,
  display_name text not null check (char_length(display_name) between 1 and 16),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  banned       boolean not null default false     -- moderation: set true to hide all of a player's records
);

-- ---------- server-issued run sessions (anti-cheat: proves the run really took this long) ----------
create table if not exists public.run_sessions (
  token      uuid primary key default gen_random_uuid(),
  player_id  uuid not null,
  level_id   int  not null references public.levels(level_id),
  started_at timestamptz not null default now(),
  used       boolean not null default false
);
create index if not exists run_sessions_player_idx on public.run_sessions (player_id, started_at desc);

-- ---------- submitted runs ----------
create table if not exists public.game_runs (
  run_id                uuid primary key,                 -- client-generated; unique => duplicate submissions are rejected
  player_id             uuid not null references public.players(player_id) on delete cascade,
  display_name_snapshot text not null,
  level_id              int  not null references public.levels(level_id),
  score                 numeric(6,2) not null check (score between 0 and 100),
  progress_percent      numeric(6,2) not null check (progress_percent between 0 and 100),
  furthest_distance     numeric(8,1) not null check (furthest_distance >= 0),
  active_play_time      numeric(8,2) not null check (active_play_time > 0),
  correct_answers       int not null check (correct_answers >= 0),
  incorrect_answers     int not null check (incorrect_answers >= 0),
  total_answered        int generated always as (correct_answers + incorrect_answers) stored,
  coins_collected       int not null check (coins_collected >= 0),
  lives_remaining       int not null check (lives_remaining between 0 and 3),
  completion_status     text not null check (completion_status in ('completed','game_over')),
  is_best               boolean not null default false,   -- this row is the player's current best for the level
  hidden                boolean not null default false,   -- moderation: set true to remove a fraudulent score
  created_at            timestamptz not null default now()
);
create index if not exists game_runs_board_idx  on public.game_runs (level_id, score desc, active_play_time asc, created_at asc) where is_best and not hidden;
create index if not exists game_runs_player_idx on public.game_runs (player_id, level_id, created_at desc);
create index if not exists game_runs_recent_idx on public.game_runs (player_id, created_at desc);

-- ---------- reports (inappropriate names / suspicious scores) ----------
create table if not exists public.reports (
  report_id  bigint generated always as identity primary key,
  run_id     uuid references public.game_runs(run_id) on delete cascade,
  reason     text not null check (char_length(reason) between 1 and 300),
  created_at timestamptz not null default now()
);

-- ---------- lock the tables down ----------
alter table public.levels       enable row level security;
alter table public.players      enable row level security;
alter table public.run_sessions enable row level security;
alter table public.game_runs    enable row level security;
alter table public.reports      enable row level security;
revoke all on public.levels, public.players, public.run_sessions, public.game_runs, public.reports from anon, authenticated;

-- ---------- helpers ----------
create or replace function public.fd_clean_name(p_name text) returns text
language sql immutable as $$
  select left(btrim(regexp_replace(coalesce(p_name, ''), '[^[:alnum:] _.\-]', '', 'g')), 16)
$$;

-- ---------- start a run (server-issued session token) ----------
create or replace function public.fd_start_run(p_player_id uuid, p_level int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_token uuid;
begin
  if p_player_id is null or not exists (select 1 from levels where level_id = p_level) then
    raise exception 'invalid_run: unknown player or level';
  end if;
  if (select count(*) from run_sessions where player_id = p_player_id and started_at > now() - interval '1 minute') >= 12 then
    raise exception 'rate_limited: too many run sessions';
  end if;
  insert into run_sessions (player_id, level_id) values (p_player_id, p_level) returning token into v_token;
  return jsonb_build_object('token', v_token, 'started_at', now());
end $$;

-- ---------- submit a finished run ----------
create or replace function public.fd_submit_run(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_player   uuid := (p->>'player_id')::uuid;
  v_run      uuid := (p->>'run_id')::uuid;
  v_token    uuid := nullif(p->>'session_token','')::uuid;
  v_level    int  := (p->>'level_id')::int;
  v_name     text := fd_clean_name(p->>'display_name');
  v_score    numeric := (p->>'score')::numeric;
  v_prog     numeric := (p->>'progress_percent')::numeric;
  v_dist     numeric := (p->>'furthest_distance')::numeric;
  v_time     numeric := (p->>'active_play_time')::numeric;
  v_ok       int := (p->>'correct_answers')::int;
  v_bad      int := (p->>'incorrect_answers')::int;
  v_coins    int := (p->>'coins_collected')::int;
  v_lives    int := (p->>'lives_remaining')::int;
  v_status   text := p->>'completion_status';
  lv         levels%rowtype;
  sess       run_sessions%rowtype;
  v_prev     game_runs%rowtype;
  v_is_best  boolean := false;
  v_rank     bigint;
  v_elapsed  numeric;
begin
  -- identity + level
  select * into lv from levels where level_id = v_level;
  if not found or v_player is null or v_run is null or char_length(v_name) < 1 then
    raise exception 'invalid_run: bad identity, level or name';
  end if;
  if exists (select 1 from players where player_id = v_player and banned) then
    raise exception 'invalid_run: player is blocked';
  end if;
  -- duplicate run
  if exists (select 1 from game_runs where run_id = v_run) then
    raise exception 'duplicate: this run was already submitted';
  end if;
  -- rate limit
  if (select count(*) from game_runs where player_id = v_player and created_at > now() - interval '1 minute') >= 6
     or (select count(*) from game_runs where player_id = v_player and created_at > now() - interval '1 day') >= 300 then
    raise exception 'rate_limited: too many submissions';
  end if;
  -- server-issued session: must exist, belong to this player+level, be unused
  select * into sess from run_sessions where token = v_token for update;
  if not found or sess.player_id <> v_player or sess.level_id <> v_level or sess.used then
    raise exception 'bad_session: missing, reused or mismatched run session';
  end if;
  v_elapsed := extract(epoch from (now() - sess.started_at));
  -- plausibility
  if v_status not in ('completed','game_over') then raise exception 'invalid_run: status'; end if;
  if v_prog < 0 or v_prog > 100 or v_score < 0 or v_score > 100 then raise exception 'invalid_run: score range'; end if;
  if abs(v_score - v_prog) > 0.05 then raise exception 'invalid_run: score does not match progress'; end if;
  if v_dist < 0 or v_dist > lv.length_m + 0.5 then raise exception 'invalid_run: distance range'; end if;
  if abs(v_prog - (v_dist / lv.length_m) * 100) > 0.3 then raise exception 'invalid_run: distance/percentage mismatch'; end if;
  if v_time <= 0 or v_time > 4 * 3600 then raise exception 'invalid_run: time range'; end if;
  -- the player moves at a constant speed, so nobody can cover this distance faster than distance/speed
  if v_time < (v_dist / lv.speed) * 0.93 then raise exception 'implausible: faster than the level speed allows'; end if;
  -- active play time is part of real elapsed time since the server issued the session
  if v_time > v_elapsed + 3 then raise exception 'implausible: more play time than real time elapsed'; end if;
  if v_ok < 0 or v_bad < 0 or v_ok + v_bad > lv.max_coins or v_coins > lv.max_coins or v_ok + v_bad > v_coins then
    raise exception 'invalid_run: trivia counts';
  end if;
  if v_lives < 0 or v_lives > 3 then raise exception 'invalid_run: lives'; end if;
  if v_status = 'completed' and (v_prog < 99.99 or v_lives < 1 or v_coins < lv.max_coins) then raise exception 'invalid_run: completion claim'; end if;
  if v_status = 'game_over' and v_lives <> 0 then raise exception 'invalid_run: game over with lives left'; end if;

  -- upsert player
  insert into players (player_id, display_name) values (v_player, v_name)
  on conflict (player_id) do update set display_name = excluded.display_name, updated_at = now();
  update run_sessions set used = true where token = v_token;

  -- personal best logic: only a strictly better run replaces the old best
  select * into v_prev from game_runs where player_id = v_player and level_id = v_level and is_best and not hidden limit 1;
  if not found or v_score > v_prev.score or (v_score = v_prev.score and v_time < v_prev.active_play_time) then
    v_is_best := true;
    update game_runs set is_best = false where player_id = v_player and level_id = v_level and is_best;
  end if;
  insert into game_runs (run_id, player_id, display_name_snapshot, level_id, score, progress_percent, furthest_distance, active_play_time,
                         correct_answers, incorrect_answers, coins_collected, lives_remaining, completion_status, is_best)
  values (v_run, v_player, v_name, v_level, v_score, v_prog, v_dist, v_time, v_ok, v_bad, v_coins, v_lives, v_status, v_is_best);

  select count(*) + 1 into v_rank from game_runs g join players pl using (player_id)
   where g.level_id = v_level and g.is_best and not g.hidden and not pl.banned and g.player_id <> v_player
     and (g.score > v_score or (g.score = v_score and g.active_play_time < v_time));
  return jsonb_build_object('ok', true, 'run_id', v_run, 'is_personal_best', v_is_best, 'level_rank', v_rank,
                            'overall_rank', public.fd_overall_rank(v_player));
end $$;

-- ---------- overall rank of one player ----------
create or replace function public.fd_overall_rank(p_player uuid) returns bigint
language sql security definer stable set search_path = public as $$
  with agg as (
    select g.player_id, sum(g.score) as total, sum(g.active_play_time) as t, max(g.created_at) as last_at
      from game_runs g join players pl using (player_id)
     where g.is_best and not g.hidden and not pl.banned group by g.player_id)
  select coalesce((select r from (select player_id, row_number() over (order by total desc, t asc, last_at asc) r from agg) x where x.player_id = p_player), null)
$$;

-- ---------- leaderboard ----------
-- p_scope: 'overall' | '1' | '2' | '3'.   p_sort: score | distance | time | correct | accuracy
create or replace function public.fd_leaderboard(p_scope text, p_sort text default 'score', p_limit int default 100, p_player_id uuid default null) returns jsonb
language plpgsql security definer stable set search_path = public as $$
declare v_rows jsonb; v_me jsonb; v_lim int := least(greatest(coalesce(p_limit, 100), 1), 200);
begin
  if p_sort not in ('score','distance','time','correct','accuracy') then p_sort := 'score'; end if;
  if p_scope = 'overall' then
    with agg as (
      select g.player_id, pl.display_name, sum(g.score) as score, sum(g.furthest_distance) as dist, sum(g.active_play_time) as t,
             sum(g.correct_answers) as ok, sum(g.incorrect_answers) as bad, count(*) as n_levels,
             bool_and(g.completion_status = 'completed') as all_done, max(g.created_at) as last_at
        from game_runs g join players pl using (player_id)
       where g.is_best and not g.hidden and not pl.banned group by g.player_id, pl.display_name),
    ranked as (select *, row_number() over (order by score desc, t asc, last_at asc) as official_rank from agg),
    shown as (
      select * from ranked
       where (p_sort <> 'time' or (all_done and n_levels = (select count(*) from levels)))
       order by case p_sort when 'score' then -score when 'distance' then -dist when 'correct' then -ok::numeric
                            when 'accuracy' then -(ok::numeric / greatest(ok + bad, 1)) end nulls last,
                case p_sort when 'time' then t end asc nulls last, official_rank
       limit v_lim)
    select coalesce(jsonb_agg(jsonb_build_object('official_rank', official_rank, 'display_name', display_name, 'score', score, 'distance', dist,
             'active_time', t, 'correct', ok, 'incorrect', bad, 'level_name', n_levels || ' level(s)', 'progress', round(score / 3.0, 1), 'date', last_at,
             'is_me', player_id = p_player_id) order by (select 1)), '[]'::jsonb) into v_rows from shown;
    select to_jsonb(r) into v_me from (
      select z.official_rank, z.score, z.dist as distance, z.t as active_time from (
        select g.player_id, row_number() over (order by sum(g.score) desc, sum(g.active_play_time) asc, max(g.created_at) asc) as official_rank,
               sum(g.score) as score, sum(g.furthest_distance) as dist, sum(g.active_play_time) as t
          from game_runs g join players pl on pl.player_id = g.player_id
         where g.is_best and not g.hidden and not pl.banned group by g.player_id) z
       where z.player_id = p_player_id) r;
  else
    with base as (
      select g.*, pl.display_name, row_number() over (order by g.score desc, g.active_play_time asc, g.created_at asc) as official_rank
        from game_runs g join players pl using (player_id)
       where g.level_id = p_scope::int and g.is_best and not g.hidden and not pl.banned),
    shown as (
      select * from base where (p_sort <> 'time' or completion_status = 'completed')
       order by case p_sort when 'score' then -score when 'distance' then -furthest_distance when 'correct' then -correct_answers::numeric
                            when 'accuracy' then -(correct_answers::numeric / greatest(total_answered, 1)) end nulls last,
                case p_sort when 'time' then active_play_time end asc nulls last, official_rank
       limit v_lim)
    select coalesce(jsonb_agg(jsonb_build_object('official_rank', official_rank, 'display_name', display_name, 'score', score, 'distance', furthest_distance,
             'active_time', active_play_time, 'correct', correct_answers, 'incorrect', incorrect_answers,
             'level_name', (select name from levels where level_id = shown.level_id), 'progress', progress_percent, 'date', created_at,
             'is_me', player_id = p_player_id, 'run_id', run_id) order by (select 1)), '[]'::jsonb) into v_rows from shown;
    select to_jsonb(r) into v_me from (
      select z.official_rank, z.score, z.furthest_distance as distance, z.active_play_time as active_time from (
        select g.player_id, g.score, g.furthest_distance, g.active_play_time,
               row_number() over (order by g.score desc, g.active_play_time asc, g.created_at asc) as official_rank
          from game_runs g join players pl on pl.player_id = g.player_id
         where g.level_id = p_scope::int and g.is_best and not g.hidden and not pl.banned) z
       where z.player_id = p_player_id) r;
  end if;
  return jsonb_build_object('rows', v_rows, 'me', v_me, 'sort', p_sort, 'scope', p_scope);
end $$;

-- ---------- a player's own statistics + personal bests ----------
create or replace function public.fd_player_stats(p_player_id uuid) returns jsonb
language sql security definer stable set search_path = public as $$
  select jsonb_build_object(
    'bests', coalesce((select jsonb_agg(jsonb_build_object('level_id', level_id, 'score', score, 'distance', furthest_distance, 'active_time', active_play_time,
              'correct', correct_answers, 'incorrect', incorrect_answers, 'date', created_at) order by level_id)
              from game_runs where player_id = p_player_id and is_best and not hidden), '[]'::jsonb),
    'runs', (select count(*) from game_runs where player_id = p_player_id),
    'overall_rank', public.fd_overall_rank(p_player_id))
$$;

-- ---------- rename ----------
create or replace function public.fd_set_display_name(p_player_id uuid, p_name text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_name text := fd_clean_name(p_name);
begin
  if char_length(v_name) < 1 then raise exception 'invalid_run: empty name'; end if;
  update players set display_name = v_name, updated_at = now() where player_id = p_player_id and not banned;
  return jsonb_build_object('ok', found, 'display_name', v_name);
end $$;

-- ---------- report a score or name ----------
create or replace function public.fd_report(p_run_id uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from game_runs where run_id = p_run_id) then raise exception 'invalid_run: unknown run'; end if;
  if (select count(*) from reports where created_at > now() - interval '1 hour') >= 200 then raise exception 'rate_limited: reports'; end if;
  insert into reports (run_id, reason) values (p_run_id, left(coalesce(p_reason, 'reported'), 300));
  return jsonb_build_object('ok', true);
end $$;

-- ---------- permissions: browsers may only call these functions ----------
revoke all on function public.fd_start_run(uuid,int), public.fd_submit_run(jsonb), public.fd_overall_rank(uuid),
  public.fd_leaderboard(text,text,int,uuid), public.fd_player_stats(uuid), public.fd_set_display_name(uuid,text), public.fd_report(uuid,text), public.fd_clean_name(text) from public;
grant execute on function public.fd_start_run(uuid,int), public.fd_submit_run(jsonb), public.fd_leaderboard(text,text,int,uuid),
  public.fd_player_stats(uuid), public.fd_set_display_name(uuid,text), public.fd_report(uuid,text) to anon, authenticated;

-- ---------- moderation cheat-sheet (run manually in the SQL editor) ----------
--   hide a fraudulent score:      update public.game_runs set hidden = true where run_id = '...';
--   block a player entirely:      update public.players  set banned = true  where player_id = '...';
--   rename an inappropriate name: update public.players  set display_name = 'Player' where player_id = '...';
--   review reports:               select * from public.reports order by created_at desc;
